mapper.update:
UPDATE SMT_AUTH_OPERATION_BATCH
SET EXPANDED_COUNT = EXPANDED_COUNT + #{appendedCount},
	EXPANSION_CURSOR = #{nextCursor},
	UPDATE_TIME = #{updatedAt}
WHERE ID = #{batchId}
	AND STATUS = 'PREPARING'
	AND EXPANSION_CURSOR = #{previousCursor}

UPDATE SMT_AUTH_OPERATION_BATCH
SET STATUS = #{status},
	EXPANSION_FINISHED_AT = #{finishedAt},
	UPDATE_TIME = #{finishedAt}
WHERE ID = #{batchId}
	AND STATUS = 'PREPARING'
	AND EXPECTED_COUNT = #{expectedCount}
	AND EXPANDED_COUNT = #{expectedCount}
